/// <summary>
///     The <c>AVASalesTableListPageFrmCtr_AVAInventSiteId_Extension</c> class is the extension for <c>SalesTableListPage</c>
/// </summary>
[ExtensionOf(formControlStr(SalesTableListPage, AVAInventSiteId))]
final class AVASalesTableListPageFrmCtr_AVAInventSiteId_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>modified</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean modified()
{
    boolean         retVal;

    FormDataSource  avaSalesTable_ds;
    InventSiteId    locInventSiteId;

    retVal              = next modified();

    avaSalesTable_ds    = this.formRun().dataSource(tableStr(SalesTable));
    locInventSiteId     = this.valueStr();

    if (locInventSiteId)
    {
        SysQuery::findOrCreateRange(avaSalesTable_ds.queryBuildDataSource(), fieldNum(SalesTable, InventSiteId)).value(queryValue(locInventSiteId));
    }
    else
    {
        SysQuery::findOrCreateRange(avaSalesTable_ds.queryBuildDataSource(), fieldNum(SalesTable, InventSiteId)).value(SysQueryRangeUtil::valueUnlimited());
    }

    avaSalesTable_ds.executeQuery();

    return retVal;
}
